//! 🧪️ A native Pack receiver preserves actual source custody and physically settles before handoff.
use super::*;
use crate::original_steps::{admission_grant,birth_grant,finished,grant_of,step_grant};
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,default_now_us};
use semio_framework_value::{RetainedCloneGrant,retirement::controlled::ControlledRetirement};
fn finish(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){for index in 0..4096{if decoder.terminal_is_empty(){return}let grant=grant_of(decoder.retirement_demands(4096).unwrap());caller.turn(grant,|cx|cx.with_original_retirement(|cx|{decoder.close_on_source(cx)?;Ok(())})).unwrap();assert!(index<4095,"original decoder close stalled");}}
fn bind(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){let stock=semio_framework_value::RetainedCloneGrant{maximum_items:1<<20,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:128};for _ in 0..16{if caller.turn(stock,|cx|Ok(decoder.admit_step(cx)?)).unwrap(){break}}assert!(decoder.source_loan_admitted(),"original decoder source loan is admitted before any birth");}
fn turn<R>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->R{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"actual original Pack receipt {p:?}");result.unwrap()}
fn born_within<O>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,d:RetirementDemand,mut admit:impl FnMut(&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>){let grant=birth_grant::<O>(d).unwrap();for index in 0..64{let mut snap=None;let mut probe=|cx:&mut StepContext<'_>|{let before=(cx.should_yield(),cx.retirement_should_yield(),cx.is_cancelled(),cx.retained_grant(),cx.fuel_remaining());let r=admit(cx);snap=Some((before,r.as_ref().ok().copied(),cx.retained_progress()));r};let done=turn(caller,decoder,grant,&mut probe);if index<5{eprintln!("[DEBUG] born turn {index} {snap:?}");}if done{return}assert!(index<63,"original birth did not settle on its exact quote")}}
#[test]
fn original_pack_typed_receiving_settles_every_original_before_unique_handoff(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let text=law["text"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize);let oracle:serde_json::Value=serde_json::from_str(&serde_json::to_string(&text).unwrap()).unwrap();
 for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]){
  let g=admission_grant(size_of::<OriginalPackReceiving<String>>());let body=g.maximum_copy_bytes;let mut caller=OriginalJobFixtureCaller::admit(OperationId(381),Generation(7),crate::original_steps::STOCK,default_now_us,u64::MAX,1<<30);let mut decoder=caller.admitted_decoder();caller.retain_dispatch().unwrap();
  let mut allow=|_|true;let mut encode=semio_framework_value::NativeEncodeControl::new(1<<24,&mut allow);let mut raw=semio_framework_pack_record::intrinsic::encode_body(&DslValue::String(text.clone()),&Default::default(),&mut encode).unwrap();let pointer=raw.as_ptr();let length=raw.len();let mut owner=None;let d=RetirementDemand{capacity_bytes:size_of::<OriginalPackReceiving<String>>(),..fixed::<OriginalPackReceiving<String>>()};
  for axis in 0..4{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3=>denied.maximum_depth=0,_=>unreachable!()}turn(&mut caller,&mut decoder,denied,|cx|{assert!(!OriginalPackReceiving::<String>::admit(&mut raw,Default::default(),cx,&mut Default::default(),&mut owner)?);Ok(())});assert!(owner.is_none());assert_eq!((raw.as_ptr(),raw.len()),(pointer,length));}
  let mut admission=Default::default();assert!((0..64).any(|_|turn(&mut caller,&mut decoder,g,|cx|OriginalPackReceiving::<String>::admit(&mut raw,Default::default(),cx,&mut admission,&mut owner))));assert!(raw.is_empty());assert_eq!(owner.as_ref().unwrap().bytes.as_ref().unwrap().as_ptr(),pointer);
  for index in 0..262144{if cut==Some(index){break}let q=owner.as_ref().unwrap().advance_grant(caller.fuel_remaining()).unwrap();let ready=turn(&mut caller,&mut decoder,q,|cx|owner.as_mut().unwrap().advance(cx));if ready{break}assert!(index<262143,"original Pack receiving did not settle");}
  let mut output=None;if cut.is_none(){assert!((0..64).any(|_|turn(&mut caller,&mut decoder,OriginalPackReceiving::<String>::take_grant().unwrap(),|cx|owner.as_mut().unwrap().take(cx,&mut output))));assert_eq!(serde_json::Value::String(output.as_ref().unwrap().clone()),oracle);}else{caller.cancel().cancel_now();}
  for index in 0..262144{if owner.as_ref().unwrap().terminal_is_empty(){break}let q=owner.as_ref().unwrap().close_grant().unwrap();turn(&mut caller,&mut decoder,q,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert!(index<262143,"original Pack cancellation did not settle");}
  turn(&mut caller,&mut decoder,step_grant(OriginalPackReceiving::<String>::release_demands()),|cx|cx.with_original_retirement(|cx|{let d=OriginalPackReceiving::<String>::release_demands();retired(cx,d,|_|{owner.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(())}));
  if let Some(output)=output{let mut close=ControlledRetirement::new(output).map_err(|(error,_)|error).unwrap();for index in 0..262144{if close.terminal_is_empty(){break}let d=close.select(body).unwrap().demands();turn(&mut caller,&mut decoder,step_grant(d),|cx|cx.with_original_retirement(|cx|{let selection=close.select(body).unwrap();retired_poll(cx,d,|effect|selection.step(effect))?;Ok(())}));assert!(index<262143);}}
  finished(caller,&mut decoder);
 }
}

fn receive_authored<T:NativeReceive<DslValue>+Sync+semio_framework_value::ToValue+PartialEq+std::fmt::Debug>(value:T){receive_authored_source(value,false)}
fn receive_authored_source<T:NativeReceive<DslValue>+Sync+semio_framework_value::ToValue+PartialEq+std::fmt::Debug>(value:T,original_value:bool){
 use semio_framework_value::ToValue;
 let input=value.to_value();let mut raw=if original_value{Vec::new()}else{let mut allow=|_|true;let mut encode=semio_framework_value::NativeEncodeControl::new(1<<24,&mut allow);semio_framework_pack_record::intrinsic::encode_body(&input,&Default::default(),&mut encode).unwrap()};let mut caller=OriginalJobFixtureCaller::admit(OperationId(383),Generation(9),crate::original_steps::STOCK,default_now_us,u64::MAX,1<<30);let mut decoder=caller.admitted_decoder();caller.retain_dispatch().unwrap();let g=admission_grant(size_of::<OriginalPackReceiving<T>>());let body=g.maximum_copy_bytes;let mut owner=None;let mut original=Some(input.clone());let mut admission=Default::default();assert!((0..64).any(|_|turn(&mut caller,&mut decoder,g,|cx|if original_value{OriginalPackReceiving::<T>::admit_value(&mut original,cx,&mut admission,&mut owner)}else{OriginalPackReceiving::<T>::admit(&mut raw,Default::default(),cx,&mut admission,&mut owner)})));for index in 0..262144{let q=owner.as_ref().unwrap().advance_grant(caller.fuel_remaining()).unwrap();if turn(&mut caller,&mut decoder,q,|cx|owner.as_mut().unwrap().advance(cx)){break}assert!(index<262143,"authored typed transaction field stalled");}let mut output=None;assert!((0..64).any(|_|turn(&mut caller,&mut decoder,OriginalPackReceiving::<T>::take_grant().unwrap(),|cx|owner.as_mut().unwrap().take(cx,&mut output))));assert_eq!(output.as_ref().unwrap(),&value);assert_eq!(output.as_ref().unwrap().to_value(),input);
 for index in 0..262144{if owner.as_ref().unwrap().terminal_is_empty(){break}let q=owner.as_ref().unwrap().close_grant().unwrap();turn(&mut caller,&mut decoder,q,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert!(index<262143);}turn(&mut caller,&mut decoder,step_grant(OriginalPackReceiving::<T>::release_demands()),|cx|cx.with_original_retirement(|cx|{let d=OriginalPackReceiving::<T>::release_demands();retired(cx,d,|_|{owner.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(())}));let mut close=RetainedCloneClose::default();for index in 0..262144{if output.is_none()&&close.is_empty(){break}let d=close.next_owner_demands::<T>(output.is_some(),&None,body).unwrap();turn(&mut caller,&mut decoder,step_grant(d),|cx|cx.with_original_retirement(|cx|{if close.is_empty(){begun(cx,d,|effect|close.begin_granted(&mut output,effect))?;}else{retired_poll(cx,d,|effect|close.step_granted(body,effect))?;}Ok(())}));assert!(index<262143);}finished(caller,&mut decoder);
}
#[test]fn original_value_receives_without_reparsing(){receive_authored_source("original λ🙂".repeat(2049),true)}
#[test]fn original_media_descriptor_receives_its_declared_wire_fields(){
 use semio_framework_value::ToValue;let descriptor=semio_plugin_decl_app::MediaArtifactDescriptor{edge_id:Some("edge".into()),port_id:Some("image:in".into()),kind_id:None,media_type:Some(semio_framework::MediaType{class:semio_framework::MediaClass::TwoD,form:semio_framework::MediaForm::Raster}),wire:semio_framework::MediaWireFormat::Intrinsic{schema:"image.schema".into()},blob_hash:None};let oracle=serde_json::json!({"edgeId":"edge","portId":"image:in","mediaType":{"class":"twoD","form":"raster"},"wire":{"kind":"intrinsic","schema":"image.schema"}});assert_eq!(serde_json::to_value(descriptor.to_value()).unwrap(),oracle);receive_authored(descriptor)
}
#[test]fn original_value_denial_keeps_the_caller_source(){
 let g=admission_grant(size_of::<OriginalPackReceiving<String>>());let mut caller=OriginalJobFixtureCaller::admit(OperationId(384),Generation(10),crate::original_steps::STOCK,default_now_us,u64::MAX,1<<30);let mut decoder=caller.admitted_decoder();caller.retain_dispatch().unwrap();let mut input=Some(DslValue::String("retained source".into()));let mut owner=None;let mut denied=g;denied.maximum_items=0;turn(&mut caller,&mut decoder,denied,|cx|{assert!(!OriginalPackReceiving::<String>::admit_value(&mut input,cx,&mut Default::default(),&mut owner)?);Ok(())});assert_eq!(input,Some(DslValue::String("retained source".into())));assert!(owner.is_none());finished(caller,&mut decoder);
}
#[test]fn original_intrinsic_pack_returns_its_actual_value_and_closes_cancelled_prefixes(){
 let oracle:serde_json::Value=serde_json::from_str(r#"{"text":"λ🙂","rows":[1,true,null]}"#).unwrap();let original=DslValue::from(oracle.clone());
 for cancel in [false,true]{let g=admission_grant(size_of::<OriginalIntrinsicReceiving>());let body=g.maximum_copy_bytes;let mut caller=OriginalJobFixtureCaller::admit(OperationId(385),Generation(11),crate::original_steps::STOCK,default_now_us,u64::MAX,1<<30);let mut decoder=caller.admitted_decoder();caller.retain_dispatch().unwrap();let mut allow=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(1<<24,&mut allow);let mut bytes=semio_framework_pack_record::intrinsic::encode_body(&original,&Default::default(),&mut control).unwrap();let mut owner=None;let mut admission=Default::default();assert!((0..64).any(|_|turn(&mut caller,&mut decoder,g,|cx|OriginalIntrinsicReceiving::admit(&mut bytes,Default::default(),cx,&mut admission,&mut owner))));for index in 0..262144{if cancel&&index==3{caller.cancel().cancel_now();break}let q=owner.as_ref().unwrap().advance_grant().unwrap();if turn(&mut caller,&mut decoder,q,|cx|owner.as_mut().unwrap().advance(cx)){break}assert!(index<262143)}let mut output=None;if !cancel{assert!((0..64).any(|_|turn(&mut caller,&mut decoder,OriginalIntrinsicReceiving::take_grant().unwrap(),|cx|owner.as_mut().unwrap().take(cx,&mut output))));assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),oracle)}for index in 0..262144{if owner.as_ref().unwrap().terminal_is_empty(){break}let q=owner.as_ref().unwrap().close_grant().unwrap();turn(&mut caller,&mut decoder,q,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert!(index<262143)}turn(&mut caller,&mut decoder,step_grant(OriginalIntrinsicReceiving::release_demands()),|cx|cx.with_original_retirement(|cx|{let d=OriginalIntrinsicReceiving::release_demands();retired(cx,d,|_|{owner.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(())}));let mut close=RetainedCloneClose::default();for _ in 0..262144{if output.is_none()&&close.is_empty(){break}let d=close.next_owner_demands::<DslValue>(output.is_some(),&None,body).unwrap();turn(&mut caller,&mut decoder,step_grant(d),|cx|cx.with_original_retirement(|cx|{if close.is_empty(){begun(cx,d,|effect|close.begin_granted(&mut output,effect))?;}else{retired_poll(cx,d,|effect|close.step_granted(body,effect))?;}Ok(())}));}assert!(output.is_none()&&close.is_empty());finished(caller,&mut decoder);}
}
#[test]fn original_transaction_origin_and_child_groups_receive_their_authored_wire_fields(){
 use semio_os_kernel as protocol;
 receive_authored(protocol::MutationOrigin::Owner);
 receive_authored(protocol::MutationOrigin::Contributed{plugin_id:"contributor λ🙂".repeat(2049),mutation_id:protocol::SchemaId("authored-operation".into()),payload_hash:protocol::PayloadHash([7;32])});
 receive_authored(protocol::MutationOrigin::Transaction{initiator:protocol::ForeignTarget{artifact_id:"original-initiator".into(),artifact_kind:"s.test.source".into(),dialect:Some("s.test.source@1#full".into())}});
 let label=semio_ui_locale::LocalizedLabel::from_fn(|terminology,locale|format!("{}:{}:λ🙂",terminology.as_str(),locale.as_str()));let child=semio_plugin_decl_emission::ChildEmit{genesis:Some(semio_plugin_decl_emission::ChildEmitGenesis{reference:semio_framework_artifact_reference::ArtifactRef{artifact_id:"original-genesis".into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.test.child".into(),standard:"1".into(),subset:"full".into()}},initial_pack:vec![1,2,127,255]}),owner:"parent/owner".into(),slot:"children".into(),child_id:"original-child".into(),ops:vec![vec![1,2],vec![3]],op_schema:protocol::SchemaId("s.test.child#edit".into()),labels:vec![label]};receive_authored(vec![child]);
}
